package in.sevasetu.amc.web;
import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import in.sevasetu.amc.security.CurrentUser;import in.sevasetu.amc.service.TokenCipher;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.io.ByteArrayResource;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;

@RestController @RequestMapping("/api/social/facebook") public class SocialController{
 private final JdbcClient db;private final TokenCipher cipher;private final ObjectMapper json;private final RestClient http;private final String appId,appSecret,version,callback,uiUrl;
 public SocialController(JdbcClient db,TokenCipher cipher,ObjectMapper json,RestClient.Builder http,@Value("${app.meta.app-id}")String appId,@Value("${app.meta.app-secret}")String appSecret,@Value("${app.meta.graph-version}")String version,@Value("${app.meta.callback-url}")String callback,@Value("${app.public-ui-url}")String uiUrl){this.db=db;this.cipher=cipher;this.json=json;this.http=http.build();this.appId=appId;this.appSecret=appSecret;this.version=version;this.callback=callback;this.uiUrl=uiUrl;}
 public record Status(boolean connected,String pageName,String pageId){}public record Connect(String authorizationUrl){}public record Published(String facebookPostId){}private record Connection(UUID id,String pageId,String pageName,String token){}
 @GetMapping("/status") Status status(@AuthenticationPrincipal CurrentUser u){CustomerController.tenant(u);return db.sql("select external_account_id,external_account_name from amcservice.social_connections where tenant_id=:t and platform='FACEBOOK' and active").param("t",u.tenantId()).query((rs,n)->new Status(true,rs.getString(2),rs.getString(1))).optional().orElse(new Status(false,null,null));}
 @GetMapping("/connect") Connect connect(@AuthenticationPrincipal CurrentUser u){CustomerController.tenant(u);configured();var state=UUID.randomUUID().toString()+UUID.randomUUID();db.sql("delete from amcservice.social_oauth_states where expires_at<now()").update();db.sql("insert into amcservice.social_oauth_states(state,tenant_id,user_id,expires_at) values(:s,:t,:u,:e)").param("s",state).param("t",u.tenantId()).param("u",u.userId()).param("e",Instant.now().plus(Duration.ofMinutes(10))).update();var url="https://www.facebook.com/"+version+"/dialog/oauth?client_id="+enc(appId)+"&redirect_uri="+enc(callback)+"&state="+enc(state)+"&scope="+enc("pages_show_list,pages_read_engagement,pages_manage_posts");return new Connect(url);}
 @GetMapping("/callback") @Transactional ResponseEntity<Void> callback(@RequestParam String code,@RequestParam String state){configured();var owner=db.sql("delete from amcservice.social_oauth_states where state=:s and expires_at>now() returning tenant_id,user_id").param("s",state).query((rs,n)->new UUID[]{rs.getObject(1,UUID.class),rs.getObject(2,UUID.class)}).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Facebook connection request expired"));var token=http.get().uri("https://graph.facebook.com/"+version+"/oauth/access_token?client_id="+enc(appId)+"&client_secret="+enc(appSecret)+"&redirect_uri="+enc(callback)+"&code="+enc(code)).retrieve().body(Map.class);var userToken=String.valueOf(token.get("access_token"));var accounts=http.get().uri("https://graph.facebook.com/"+version+"/me/accounts?fields=id,name,access_token&access_token="+enc(userToken)).retrieve().body(Map.class);var pages=(List<Map<String,Object>>)accounts.get("data");if(pages==null||pages.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"No manageable Facebook Page was returned");var page=pages.getFirst();var id=UUID.randomUUID();db.sql("insert into amcservice.social_connections(id,tenant_id,platform,external_account_id,external_account_name,encrypted_access_token,connected_by) values(:id,:t,'FACEBOOK',:page,:name,:token,:u) on conflict(tenant_id,platform) do update set external_account_id=excluded.external_account_id,external_account_name=excluded.external_account_name,encrypted_access_token=excluded.encrypted_access_token,connected_by=excluded.connected_by,active=true,updated_at=now()").param("id",id).param("t",owner[0]).param("page",String.valueOf(page.get("id"))).param("name",String.valueOf(page.get("name"))).param("token",cipher.encrypt(String.valueOf(page.get("access_token")))).param("u",owner[1]).update();return ResponseEntity.status(HttpStatus.FOUND).location(URI.create(uiUrl+"/?facebook=connected")).build();}
 @PostMapping(value="/publish",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) Published publish(@AuthenticationPrincipal CurrentUser u,@RequestPart(value="caption",required=false)String caption,@RequestPart("files")List<MultipartFile> files){CustomerController.tenant(u);caption=caption==null?"":caption;if(files.isEmpty()||files.size()>10)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose one video or up to 10 images");var videos=files.stream().filter(f->f.getContentType()!=null&&f.getContentType().startsWith("video/")).count();if(videos>0&&(videos!=1||files.size()!=1))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A video must be published by itself");var connection=connection(u.tenantId());var postId=UUID.randomUUID();var type=videos==1?"VIDEO":"IMAGES";db.sql("insert into amcservice.social_posts(id,tenant_id,connection_id,platform,media_type,caption,media_count,status,created_by) values(:id,:t,:c,'FACEBOOK',:type,:caption,:count,'PUBLISHING',:u)").param("id",postId).param("t",u.tenantId()).param("c",connection.id()).param("type",type).param("caption",caption).param("count",files.size()).param("u",u.userId()).update();try{String external=videos==1?publishVideo(connection,caption,files.getFirst()):publishImages(connection,caption,files);db.sql("update amcservice.social_posts set status='PUBLISHED',external_post_id=:external,published_at=now() where id=:id").param("external",external).param("id",postId).update();return new Published(external);}catch(Exception e){var error=String.valueOf(e.getMessage());db.sql("update amcservice.social_posts set status='FAILED',error_message=:error where id=:id").param("error",error.substring(0,Math.min(1000,error.length()))).param("id",postId).update();throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Facebook rejected the post. Check the Page connection and media format.");}}
 private String publishImages(Connection c,String caption,List<MultipartFile> files)throws Exception{var attached=new ArrayList<Map<String,String>>();for(var f:files){var result=sendMultipart("https://graph.facebook.com/"+version+"/"+c.pageId()+"/photos",c.token(),Map.of("published","false"),f);attached.add(Map.of("media_fbid",String.valueOf(result.get("id"))));}var form=new LinkedMultiValueMap<String,String>();form.add("message",caption);form.add("attached_media",json.writeValueAsString(attached));form.add("access_token",c.token());var response=http.post().uri("https://graph.facebook.com/"+version+"/"+c.pageId()+"/feed").contentType(MediaType.APPLICATION_FORM_URLENCODED).body(form).retrieve().body(Map.class);return String.valueOf(response.get("id"));}
 private String publishVideo(Connection c,String caption,MultipartFile file)throws Exception{var response=sendMultipart("https://graph.facebook.com/"+version+"/"+c.pageId()+"/videos",c.token(),Map.of("description",caption),file);return String.valueOf(response.get("id"));}
 private Map sendMultipart(String url,String token,Map<String,String> fields,MultipartFile file)throws Exception{var body=new LinkedMultiValueMap<String,Object>();fields.forEach(body::add);body.add("access_token",token);body.add("source",new ByteArrayResource(file.getBytes()){public String getFilename(){return Optional.ofNullable(file.getOriginalFilename()).orElse("upload");}});return http.post().uri(url).contentType(MediaType.MULTIPART_FORM_DATA).body(body).retrieve().body(Map.class);}
 private Connection connection(UUID tenant){return db.sql("select id,external_account_id,external_account_name,encrypted_access_token from amcservice.social_connections where tenant_id=:t and platform='FACEBOOK' and active").param("t",tenant).query((rs,n)->new Connection(rs.getObject(1,UUID.class),rs.getString(2),rs.getString(3),cipher.decrypt(rs.getString(4)))).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"Connect a Facebook Page first"));}
 private void configured(){if(appId.isBlank()||appSecret.isBlank())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Facebook integration is not configured");}private String enc(String value){return URLEncoder.encode(value,StandardCharsets.UTF_8);}
}
